// Safety-net filter: anything still sitting in the raw Inbox after a
// grace period has EITHER been missed by the webhook trigger, or is
// mid-processing by a very recent, still-in-flight Main execution.
// The grace period exists purely to avoid racing the latter case --
// Core Processor's own lock would keep us safe even without it, but
// there's no reason to manufacture unnecessary lock contention.
const GRACE_MS = 10 * 60 * 1000; // 10 minutes
const now = Date.now();

return $input.all().filter((inputItem) => {
  const item = inputItem.json;
  const raw = item.receivedDateTime || item.createdDateTime;
  if (!raw) return false;
  const t = new Date(raw).getTime();
  if (isNaN(t)) return false;
  return (now - t) > GRACE_MS;
});
